        states: r.stateCount,
        errors: r.errors.length,
        warnings: r.warnings.length,
    })), [
        { type: 'field', key: 'skill' },
        { type: 'field', key: 'status' },
        { type: 'field', key: 'states' },
        { type: 'field', key: 'errors' },
        { type: 'field', key: 'warnings' },
    ]);
    const allErrors = [];
    const allWarnings = [];
    for (const r of results) {
        for (const e of r.errors)
