fd13-1496-7d30-9e72-c0618c59289e","01a0fd13-14bb-7080-98b6-af5dab818239"],req=createRequire("C:/Users/brand/.codex/worktrees/skill-cli-signals-20261002/apps/axi/dist/cli/index.js"),r=await import(pathToFileURL(req.resolve("@reactive-skills/runtime")));
