const actual=snapshot(\"source-a/eval-report\");assert.deepEqual(Object.keys(actual).map(x=>x.replace(\"source-a/eval-report/\",\"\")).sort(),[...expected].sort());
const sourceA=snapshot(\"source-a\");for(const [f,h]of Object.entries(baseline.source_a))assert.equal(sourceA[f],h);assert.deepEqual(Object.keys(sourceA).filter(x=>"'!Object.hasOwn(baseline.source_a,x)).sort(),Object.keys(actual).sort());
assert.deepEqual(snapshot("source-b"),baseline.source_b);assert.deepEqual(snapshot("distribution"),baseline.distribution);assert.equal(fs.readFileSync("sources.json","utf8"),baseline.registries.workspace);assert.equal(fs.readFileSync("home/.agents/sources.json","utf8"),baseline.registries.fixture_home);
