const ledgers=[];for(const [i,runId]of ids.entries()){const store=new r.EventStore({skillId:\"eval-report\",workspaceDir:process.cwd(),runId,enableSqlite:true,readOnly:true});try{const events=store.getAll();assert.ok(events.every(e=>e.run_id===runId));const evidence=events.filter(e=>e.type===\"DECISION_RECORDED\"&&e.payload.kind===\"validation_executor_coverage\");assert.equal(evidence.length,1);assert.equal(evidence[0].payload.coverage.llm_executor_runs,0);const transitions=events.filter(e=>e.type===\"STATE_TRANSITION\");assert.equal(transitions.length,i===0?3:i===1?2:3);if(i>0)assert.ok(events.some(e=>e.type===\"EVENT_BUBBLED\"&&e.payload.handledAt===\"WORK\"));ledgers.push({run_id:runId,persisted_events:events.length,transitions:transitions.length,coverage_recorded:true});}finally{store.close();}}
console.log(JSON.stringify({status:\"COMPLETE\",created_files:Object.keys(actual),source_a_extra_files:0,source_b_unchanged:true,distribution_unchanged:true,registries_unchanged:true,ledgers,runtime_artifacts:Object.keys(snapshot(\".reactive\"))},null,2));'"

